-- 세트 367: SQL 데이터 변경 손연습: INSERT·UPDATE·DELETE, INSERT ... SELECT, 트랜잭션(COMMIT·ROLLBACK)
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_sql_modify_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (367, 1, '행 하나 추가하기 (INSERT)', '**배경** — `INSERT`·`UPDATE`·`DELETE` 는 표의 데이터를 **바꾸는** 문장입니다. 이 세트의 문제는 작은 가게 데이터베이스 `shop`(`mariadb shop -e ''쿼리''` 로 접속해 실행)을 씁니다. 문제마다 처음 상태에서 다시 시작하니 마음껏 시도해도 됩니다.

- `customers`(고객 6명): `id`, `name`, `city`(Seoul·Busan·Daegu) / `customers_backup`: 같은 구조의 빈 테이블
- `products`(상품 5개): `id`, `name`, `price`, `category`(stationery·electronics)
- `orders`(주문 10건): `id`, `customer_id`, `product_id`, `qty`
- `accounts`(계좌 2개): `id`, `owner`, `balance` (kim 10000, lee 5000)

컬럼 구성이 헷갈리면 `DESCRIBE 테이블;` 로 볼 수 있습니다.

**문제** — `customers` 에 새 고객을 추가하세요: `id` 7, `name` `song`, `city` `Daegu`.', '`INSERT INTO 테이블 VALUES (값, 값, ...);` 처럼 컬럼 순서대로 값을 줍니다. 문자열은 작은따옴표로 감싸세요.', 'mariadb shop -e "INSERT INTO customers VALUES (7, ''song'', ''Daegu'');"
mariadb shop -e ''SELECT * FROM customers;''

# INSERT 로 행을 추가한다. 컬럼 순서(id, name, city)대로 값을 준다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers\\")\\" = \\"kim,lee,park,choi,jung,han,song\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT city FROM customers WHERE id = 7\\")\\" = \\"Daegu\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "고객이 7명이 되고 마지막이 song 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers\\")\\" = \\"kim,lee,park,choi,jung,han,song\\" ]"]}, {"label": "song 의 city 가 Daegu 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT city FROM customers WHERE id = 7\\")\\" = \\"Daegu\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 2, '여러 행 한 번에 추가하기', '`products` 에 두 상품을 **한 문장으로** 추가하세요: (6, `cable`, 2000, `electronics`), (7, `stapler`, 5000, `stationery`).', '`VALUES` 뒤에 괄호 묶음을 쉼표로 이어 쓰면 한 번에 여러 행을 넣을 수 있습니다.', 'mariadb shop -e "INSERT INTO products VALUES (6, ''cable'', 2000, ''electronics''), (7, ''stapler'', 5000, ''stationery'');"

# VALUES (...), (...) 로 여러 행을 한 번에', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM products\\")\\" = \\"pen,notebook,mouse,keyboard,monitor,cable,stapler\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(price ORDER BY id) FROM products\\")\\" = \\"1000,3000,15000,40000,200000,2000,5000\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(category ORDER BY id) FROM products\\")\\" = \\"stationery,stationery,electronics,electronics,electronics,electronics,stationery\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "상품 7개의 이름 순서가 맞다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM products\\")\\" = \\"pen,notebook,mouse,keyboard,monitor,cable,stapler\\" ]"]}, {"label": "가격이 맞다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(price ORDER BY id) FROM products\\")\\" = \\"1000,3000,15000,40000,200000,2000,5000\\" ]"]}, {"label": "분류가 맞다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(category ORDER BY id) FROM products\\")\\" = \\"stationery,stationery,electronics,electronics,electronics,electronics,stationery\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 3, '한 행만 고치기 (UPDATE ... WHERE)', '`products` 에서 `pen` 의 가격을 **1200** 으로 바꾸세요. 다른 상품은 그대로여야 합니다.', '`UPDATE 테이블 SET 컬럼 = 값 WHERE 조건;` 입니다. `WHERE` 를 빠뜨리면 모든 행이 바뀌니 조심하세요.', 'mariadb shop -e "UPDATE products SET price = 1200 WHERE name = ''pen'';"
mariadb shop -e ''SELECT * FROM products;''

# WHERE 로 대상 행을 좁힌 뒤 SET 으로 바꾼다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(price ORDER BY id) FROM products\\")\\" = \\"1200,3000,15000,40000,200000\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "pen 만 1200 이고 나머지 가격은 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(price ORDER BY id) FROM products\\")\\" = \\"1200,3000,15000,40000,200000\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 4, '조건에 맞는 여러 행 고치기', '`electronics` 분류 상품의 가격을 모두 **1000 원씩 올리세요**. `stationery` 는 그대로여야 합니다.', '`SET price = price + 1000` 처럼 현재 값을 이용해 계산할 수 있습니다. 대상은 `WHERE category = ...` 로 좁힙니다.', 'mariadb shop -e "UPDATE products SET price = price + 1000 WHERE category = ''electronics'';"

# SET price = price + 값 으로 현재 값 기준으로 바꾼다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(price ORDER BY id) FROM products\\")\\" = \\"1000,3000,16000,41000,201000\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "electronics 만 1000 씩 올랐다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(price ORDER BY id) FROM products\\")\\" = \\"1000,3000,16000,41000,201000\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 5, '한 행 지우기 (DELETE ... WHERE)', '`orders` 에서 주문 번호(`id`) **10** 인 주문 하나만 삭제하세요.', '`DELETE FROM 테이블 WHERE 조건;` 입니다. `WHERE` 없이 쓰면 테이블의 모든 행이 지워집니다.', 'mariadb shop -e ''DELETE FROM orders WHERE id = 10;''
mariadb shop -e ''SELECT id FROM orders;''

# DELETE 는 WHERE 로 대상 행을 좁혀 지운다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(id ORDER BY id) FROM orders\\")\\" = \\"1,2,3,4,5,6,7,8,9\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "10번만 사라지고 1~9번이 남았다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(id ORDER BY id) FROM orders\\")\\" = \\"1,2,3,4,5,6,7,8,9\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 6, '조건에 맞는 여러 행 지우기', '`orders` 에서 수량(`qty`)이 **1** 인 주문을 모두 삭제하세요.', '조건에 맞는 행은 몇 개든 한 문장으로 지울 수 있습니다. 먼저 `SELECT` 로 어떤 행이 지워질지 확인해 보는 습관이 안전합니다.', 'mariadb shop -e ''SELECT * FROM orders WHERE qty = 1;''
mariadb shop -e ''DELETE FROM orders WHERE qty = 1;''

# 지우기 전에 같은 WHERE 로 SELECT 해서 대상을 확인한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(id ORDER BY id) FROM orders\\")\\" = \\"1,3,5,7,8,9\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "수량 1 인 주문(2,4,6,10번)이 지워지고 나머지가 남았다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(id ORDER BY id) FROM orders\\")\\" = \\"1,3,5,7,8,9\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 7, '트랜잭션으로 이체하기 (COMMIT)', '`accounts` 에서 `kim` 이 `lee` 에게 **3000** 을 이체합니다. 출금(`kim` -3000)과 입금(`lee` +3000)을 **하나의 트랜잭션** 안에서 처리하고 확정(`COMMIT`)하세요. 한 번의 `mariadb -e` 안에서 문장들을 `;` 로 이어 쓰세요.', '`START TRANSACTION;` 으로 시작하고 `COMMIT;` 으로 확정합니다. 같은 접속(같은 `-e` 문자열) 안에 넣어야 하나의 트랜잭션이 됩니다.', 'mariadb shop -e "START TRANSACTION; UPDATE accounts SET balance = balance - 3000 WHERE owner = ''kim''; UPDATE accounts SET balance = balance + 3000 WHERE owner = ''lee''; COMMIT;"
mariadb shop -e ''SELECT * FROM accounts;''

# 두 UPDATE 를 한 트랜잭션으로 묶고 COMMIT 으로 확정한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(balance ORDER BY id) FROM accounts\\")\\" = \\"7000,8000\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "kim 7000, lee 8000 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(balance ORDER BY id) FROM accounts\\")\\" = \\"7000,8000\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 8, '되돌리기 (ROLLBACK)', '트랜잭션 안에서 **모든 계좌의 잔액을 0 으로** 바꾼 뒤, 그 시점의 잔액 합계를 `SELECT SUM(balance) AS total FROM accounts` 로 조회해 출력을 **`/tmp/q8.txt`** 에 저장하고, 마지막에 `ROLLBACK` 으로 **취소**하세요. 끝난 뒤 실제 잔액은 원래대로여야 합니다. 한 번의 `mariadb -e` 안에서 처리하세요.', '`START TRANSACTION;` 뒤의 변경은 `COMMIT` 하기 전까지 되돌릴 수 있습니다. 트랜잭션 안에서 조회하면 변경된 값이 보이고, `ROLLBACK` 하면 모두 취소됩니다.', 'mariadb shop -e ''START TRANSACTION; UPDATE accounts SET balance = 0; SELECT SUM(balance) AS total FROM accounts; ROLLBACK;'' > /tmp/q8.txt
cat /tmp/q8.txt
mariadb shop -e ''SELECT * FROM accounts;''

# 트랜잭션 안에서는 0 으로 보이지만 ROLLBACK 하면 원래대로 돌아온다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(cat /tmp/q8.txt)\\" = \\"$(printf \\"total\\\\n0\\")\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(balance ORDER BY id) FROM accounts\\")\\" = \\"10000,5000\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q8.txt 에 트랜잭션 안의 합계 0 이 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q8.txt)\\" = \\"$(printf \\"total\\\\n0\\")\\" ]"]}, {"label": "ROLLBACK 으로 잔액이 그대로다 (10000, 5000)", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(balance ORDER BY id) FROM accounts\\")\\" = \\"10000,5000\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 9, '조회 결과를 다른 테이블에 복사하기 (INSERT ... SELECT)', '`customers` 에서 도시가 `Seoul` 인 고객을 `customers_backup` (구조는 같고 비어 있음)에 **복사** 하세요. `customers` 는 그대로 6명이어야 합니다.', '`INSERT INTO 대상 SELECT ... FROM 원본 WHERE ...;` 로 조회 결과를 곧바로 다른 테이블에 넣을 수 있습니다.', 'mariadb shop -e "INSERT INTO customers_backup SELECT * FROM customers WHERE city = ''Seoul'';"
mariadb shop -e ''SELECT * FROM customers_backup;''

# INSERT ... SELECT 로 조회 결과를 다른 테이블에 복사한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE customers_backup (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);\\nCREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(30) NOT NULL, balance INT NOT NULL);\\nINSERT INTO accounts VALUES (1,\\"kim\\",10000),(2,\\"lee\\",5000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers_backup\\")\\" = \\"kim,park,han\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers\\")\\" = \\"kim,lee,park,choi,jung,han\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "백업에 Seoul 고객 3명이 들어갔다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers_backup\\")\\" = \\"kim,park,han\\" ]"]}, {"label": "원본 customers 는 6명 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(name ORDER BY id) FROM customers\\")\\" = \\"kim,lee,park,choi,jung,han\\" ]"]}]', '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 10, 'WHERE 없이 UPDATE 하면?', '`UPDATE products SET price = 0;` 처럼 **WHERE 없이** 실행하면 어떻게 될까요?', '대상을 좁히는 조건이 없다는 점에 주목하세요.', NULL, NULL, '[]', 'choice', '["가장 첫 번째 행의 가격만 0 으로 바뀐다", "테이블의 모든 행의 가격이 0 으로 바뀐다", "문법 오류가 나서 아무 것도 바뀌지 않는다", "마지막에 입력한 행의 가격만 0 으로 바뀐다"]', 1, 'WHERE 가 없으면 조건으로 좁히지 않으므로 **모든 행** 이 바뀝니다. 그래서 UPDATE·DELETE 는 먼저 같은 WHERE 로 SELECT 해서 대상을 확인하고, 중요한 변경은 트랜잭션 안에서 하는 것이 안전합니다.', NULL, NULL, NULL, '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 11, '변경 확정하기', '트랜잭션 안에서 한 변경을 **영구히 확정** 하는 문장입니다. 빈칸을 채우세요.', '취소가 아니라 확정이에요.', NULL, NULL, '[]', 'fill', '["COMMIT", "ROLLBACK", "SAVE", "FINISH"]', NULL, '`COMMIT` 은 트랜잭션의 변경을 확정합니다. `ROLLBACK` 은 반대로 변경을 취소합니다. `SAVE`·`FINISH` 는 이 자리에 쓰는 문장이 아닙니다.', '[0]', 'START TRANSACTION; UPDATE accounts SET balance = 0 WHERE id = 1; {0};', NULL, '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]'),
  (367, 12, '이체 트랜잭션의 흐름', '한 계좌에서 빼서 다른 계좌에 더하는 이체를 트랜잭션으로 처리하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '시작 → 변경들 → 확인 → 확정 순서예요.', NULL, NULL, '[]', 'order', '["`START TRANSACTION;`", "`UPDATE accounts SET balance = balance - 3000 WHERE owner = ''kim'';`", "`UPDATE accounts SET balance = balance + 3000 WHERE owner = ''lee'';`", "`SELECT * FROM accounts;` 로 결과를 확인한다", "`COMMIT;`"]', NULL, '트랜잭션을 시작하고, 출금과 입금을 모두 수행한 뒤, 결과를 확인하고 문제가 없으면 `COMMIT` 합니다. 문제가 있으면 `COMMIT` 대신 `ROLLBACK` 으로 취소합니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "MariaDB INSERT", "url": "https://mariadb.com/kb/en/insert/"}, {"title": "MariaDB UPDATE", "url": "https://mariadb.com/kb/en/update/"}, {"title": "MariaDB DELETE", "url": "https://mariadb.com/kb/en/delete/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}, {"title": "MariaDB 트랜잭션 (START TRANSACTION, COMMIT, ROLLBACK)", "url": "https://mariadb.com/kb/en/start-transaction/"}]');
